import { shallot } from "@dylanebert/shallot/bun";
import { plugin } from "bun";

plugin(shallot({ root: import.meta.dir }));
import { pipelineWarnings, TIMEOUT } from "@dylanebert/shallot/testing";
import { expect, type Page, test } from "playwright/test";

const entry = "**/assets/index-*.js";
const loadingOverlay = "body > [data-shallot-loading]";

async function holdEntry(page: Page) {
    let release!: () => void;
    let reached!: () => void;
    const held = new Promise<void>((resolve) => {
        release = resolve;
    });
    const requested = new Promise<void>((resolve) => {
        reached = resolve;
    });
    await page.route(entry, async (route) => {
        reached();
        await held;
        await route.continue();
    });
    await page.goto("/", { waitUntil: "commit" });
    await requested;
    return release;
}

async function labelInkPixels(page: Page): Promise<number> {
    const screenshot = await page.screenshot();
    return page.evaluate(async (base64) => {
        const bootstrap = document.querySelector("[data-shallot-bootstrap]");
        const background = bootstrap
            ? getComputedStyle(bootstrap).backgroundColor.match(/\d+/g)!.map(Number)
            : [];
        const text = bootstrap?.firstChild;
        if (!text || text.nodeType !== Node.TEXT_NODE) return 0;
        const range = document.createRange();
        range.selectNodeContents(text);
        const bounds = range.getBoundingClientRect();
        if (bounds.width === 0 || bounds.height === 0) return 0;

        const image = await createImageBitmap(
            new Blob([Uint8Array.from(atob(base64), (value) => value.charCodeAt(0))]),
        );
        const canvas = document.createElement("canvas");
        canvas.width = image.width;
        canvas.height = image.height;
        const context = canvas.getContext("2d")!;
        context.drawImage(image, 0, 0);
        const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
        image.close();

        let contrasting = 0;
        for (
            let y = Math.max(0, Math.floor(bounds.top));
            y < Math.min(canvas.height, Math.ceil(bounds.bottom));
            y++
        ) {
            for (
                let x = Math.max(0, Math.floor(bounds.left));
                x < Math.min(canvas.width, Math.ceil(bounds.right));
                x++
            ) {
                const offset = (y * canvas.width + x) * 4;
                if (
                    Math.abs(pixels[offset]! - background[0]!) > 4 &&
                    Math.abs(pixels[offset + 1]! - background[1]!) > 4 &&
                    Math.abs(pixels[offset + 2]! - background[2]!) > 4
                )
                    contrasting++;
            }
        }
        return contrasting;
    }, screenshot.toString("base64"));
}

async function expectPaintedLabel(page: Page) {
    expect(
        await labelInkPixels(page),
        "screenshot has visible label ink against the bootstrap background",
    ).toBeGreaterThan(20);
}

test.use(pipelineWarnings);

test("the first frame does not resize a configured canvas", async ({ page }) => {
    await page.addInitScript(() => {
        const configured = new WeakSet<HTMLCanvasElement>();
        const writes: string[] = [];
        Object.assign(window, { configuredCanvasResizes: writes });
        const configure = GPUCanvasContext.prototype.configure;
        GPUCanvasContext.prototype.configure = function (descriptor) {
            configured.add(this.canvas as HTMLCanvasElement);
            return configure.call(this, descriptor);
        };
        for (const axis of ["width", "height"] as const) {
            const descriptor = Object.getOwnPropertyDescriptor(HTMLCanvasElement.prototype, axis)!;
            Object.defineProperty(HTMLCanvasElement.prototype, axis, {
                ...descriptor,
                set(value: number) {
                    if (configured.has(this) && descriptor.get!.call(this) !== value)
                        writes.push(axis);
                    descriptor.set!.call(this, value);
                },
            });
        }
    });
    await page.goto("/");
    await page.waitForFunction(() =>
        performance
            .getEntriesByType("measure")
            .some((entry) => entry.name.endsWith(":first-update")),
    );
    expect(
        await page.evaluate(
            () =>
                (window as unknown as { configuredCanvasResizes: string[] })
                    .configuredCanvasResizes,
        ),
    ).toEqual([]);
});

test("the first frame has no late-pipeline warning", async ({ page }) => {
    await page.goto("/");
    await page.waitForFunction(() =>
        performance
            .getEntriesByType("measure")
            .some((entry) => entry.name.endsWith(":first-update")),
    );
});

test("minimal paints its bootstrap before the held application entry", async ({ page }) => {
    const release = await holdEntry(page);
    await expectPaintedLabel(page);
    if (process.env.SHALLOT_CAPTURE_DIR) {
        await page.evaluate(() => document.fonts.ready);
        await page.mouse.move(0, 0);
        await page.screenshot({ path: `${process.env.SHALLOT_CAPTURE_DIR}/bootstrap.png` });
    }
    release();
});

test("the screenshot witness rejects a blank bootstrap control", async ({ page }) => {
    const release = await holdEntry(page);
    await page.addStyleTag({
        content: "[data-shallot-bootstrap] { color: transparent !important; }",
    });
    expect(
        await labelInkPixels(page),
        "transparent bootstrap text leaves no contrasting label pixels",
    ).toBe(0);
    release();
});

test("releasing the entry hands off to the loading screen and starts the scene", async ({
    page,
}) => {
    const release = await holdEntry(page);
    await expectPaintedLabel(page);
    release();
    await expect(page.locator("[data-shallot-bootstrap]")).toHaveCount(0);
    await expect(page.locator(loadingOverlay)).toBeVisible();
    await expect(page.locator(loadingOverlay)).toHaveCount(0, { timeout: TIMEOUT.browser });

    const canvas = page.locator("#canvas");
    await expect(canvas).toBeVisible();
    await expect
        .poll(
            async () => {
                const screenshot = await canvas.screenshot();
                return page.evaluate(async (base64) => {
                    const image = await createImageBitmap(
                        new Blob([Uint8Array.from(atob(base64), (value) => value.charCodeAt(0))]),
                    );
                    const canvas = document.createElement("canvas");
                    canvas.width = image.width;
                    canvas.height = image.height;
                    const context = canvas.getContext("2d")!;
                    context.drawImage(image, 0, 0);
                    const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
                    image.close();
                    let visible = 0;
                    for (let i = 0; i < pixels.length; i += 4) {
                        if (
                            pixels[i + 3]! > 0 &&
                            (pixels[i]! > 35 || pixels[i + 1]! > 35 || pixels[i + 2]! > 35)
                        )
                            visible++;
                    }
                    return visible;
                }, screenshot.toString("base64"));
            },
            { timeout: TIMEOUT.browser },
        )
        .toBeGreaterThan(100);
});

test("entry evaluation, dependency rejection, entry load abort, and unhandled rejection settle the bootstrap", async ({
    page,
}) => {
    for (const failure of ["evaluation", "dependency", "load", "rejection"] as const) {
        await page.route(entry, async (route) => {
            if (failure === "load") await route.abort();
            else
                await route.fulfill({
                    status: 200,
                    contentType: "text/javascript",
                    body:
                        failure === "evaluation"
                            ? 'throw new Error("controlled entry evaluation failure");'
                            : failure === "rejection"
                              ? 'void Promise.reject(new Error("controlled entry rejection"));'
                              : 'import "./missing-startup-dependency.js";',
                });
        });
        await page.route("**/assets/missing-startup-dependency.js", (route) => route.abort());
        await page.goto("/", { waitUntil: "commit" });
        const bootstrap = page.locator("[data-shallot-bootstrap]");
        await expect(bootstrap).toHaveAttribute("data-state", "error");
        await expect(bootstrap).toHaveAttribute("role", "alert");
        await expect(bootstrap).toContainText("Unable to start this application");
        await page.unrouteAll({ behavior: "wait" });
        await page.goto("about:blank");
    }
});
import { shallot } from "@dylanebert/shallot/vite";

export default {
    plugins: [shallot()],
};
import {
    Camera,
    component,
    DirectionalLight,
    GlobalAmbientLight,
    lookAtRotation,
    Materials,
    MeshInstance,
    MeshMaterial,
    type Plugin,
    StandardMaterial,
    StandardRenderer,
    Transform,
    type World,
} from "@dylanebert/shallot";
import { Orbit, OrbitPlugin } from "@dylanebert/shallot/extras";

export const WelcomeCube = component("WelcomeCube", {});

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xd8e4ff;
    ambient.brightness = 380;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xffe8cc, illuminance: 6000 });
    world.storage(DirectionalLight).shadowMapsEnabled.set(sun, 1);

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 6, yaw: 0.7, pitch: 0.4 });
    world.add(camera, Transform);

    const materials = world.resource(Materials);
    const cubeMaterial = materials.add(
        StandardMaterial({
            baseColor: [0.72, 0.4, 0.05, 1],
            perceptualRoughness: 0.38,
        }),
    );
    const cube = world.create();
    world.add(cube, MeshInstance);
    world.add(cube, MeshMaterial, cubeMaterial);
    world.add(cube, Transform, { translation: [0, 0, 0] });
    world.add(cube, WelcomeCube);

    const groundMaterial = materials.add(
        StandardMaterial({
            baseColor: [0.085, 0.08, 0.072, 1],
            perceptualRoughness: 0.82,
        }),
    );
    const ground = world.create();
    world.add(ground, MeshInstance);
    world.add(ground, MeshMaterial, groundMaterial);
    world.add(ground, Transform, {
        translation: [0, -0.6, 0],
        scale: [4, 0.2, 4],
    });
}

const SpinCube = {
    name: "Welcome/SpinCube",
    update(world: World): void {
        const halfAngle = world.time.deltaTime * 0.65 * 0.5;
        if (halfAngle === 0) return;
        const sine = Math.sin(halfAngle);
        const cosine = Math.cos(halfAngle);
        const rotation = world.storage(Transform).rotation;
        for (const eid of world.query([WelcomeCube])) {
            const y = rotation.y.get(eid);
            const w = rotation.w.get(eid);
            rotation.set(eid, 0, y * cosine + w * sine, 0, w * cosine - y * sine);
        }
    },
};

export const Welcome: Plugin = {
    name: "Welcome",
    components: [WelcomeCube],
    dependencies: [OrbitPlugin],
    initialize: makeScene,
    systems: [SpinCube],
};
import { expect, test } from "bun:test";
import { createApp, Transform } from "@dylanebert/shallot";
import { Welcome, WelcomeCube } from "./index";

test("the welcome cube turns when the world steps", async () => {
    const app = await createApp({ defaults: false, plugins: [Welcome] });
    try {
        const cube = [...app.world.query([WelcomeCube])][0];
        expect(cube).toBeDefined();
        const rotation = app.world.storage(Transform).rotation;
        const before = [rotation.y.get(cube!), rotation.w.get(cube!)];

        app.world.step(1 / 60);

        expect([rotation.y.get(cube!), rotation.w.get(cube!)]).not.toEqual(before);
    } finally {
        app.dispose();
    }
});
