    TextPlugin,
    Time,
    Transform,
    u8,
    u32,

const SampleInteraction: System = {
    name: "sample",
    group: "setup",
    after: PlayerPlugin.systems?.filter((system) => system.group === "setup"),
    update(world) {
        const devices = world.resource(Devices);
        const input = world.storage(InteractionInput);
        for (const camera of world.query(INPUTS)) {
            let yaw: number | undefined;
            let pitch = 0;
            for (const player of world.query(LOCAL_PLAYERS)) {
                if (world.storage(Player).camera.get(player) !== camera) continue;
                yaw = world.storage(LocalPlayer).viewYaw.get(player);
                pitch = world.storage(LocalPlayer).viewPitch.get(player);
            }
            const target = focus(world, camera, yaw, pitch);
            const held = Number(devices.enabled && devices.keys.held.has("KeyE"));
            if (target !== input.target.get(camera) || !held) {
                input.cancelled.set(camera, 1);
                const presses = world.storage(InteractionPress);
                for (const press of world.query(PRESSES)) {
                    const pending = presses.target.get(press);
                    if (
                        presses.camera.get(press) === camera &&
                        world.has(pending, Usable) &&
                        world.storage(Usable).action.get(pending) === Action.Hold
                    )
                        presses.target.set(press, 0);
                }
            }
            input.target.set(camera, target);
            input.held.set(camera, held);
            if (devices.enabled && !world.time.paused && devices.keys.pressed.has("KeyE")) {
                const press = world.create();
                world.add(press, InteractionPress, { camera, target });
            }
        }
    },
};

import { afterEach, expect, test } from "bun:test";
import {
    Body,
    BodyType,
    Content,
    createApp,
    InputPlugin,
    Outline,
    PointLight,
    pressKey,
    releaseKey,
    Shape,
    StandardPhysicsPlugin,
    Text,
    Transform,
    TransformPlugin,
    type World,
} from "@dylanebert/shallot";
import { Action, Hint, InteractionInput, InteractPlugin, Usable } from "./interact";

const apps: Awaited<ReturnType<typeof createApp>>[] = [];
afterEach(() => {
    for (const app of apps) app.dispose();
    apps.length = 0;
});
async function scene(action: number = Action.Lamp) {
    const app = await createApp({
        defaults: false,
        plugins: [
            {
                name: "GameCheck",
                recovery: "stateless",
                dependencies: [StandardPhysicsPlugin, InputPlugin, TransformPlugin],
                components: [...InteractPlugin.components!, Outline, PointLight, Text],
                systems: InteractPlugin.systems,
            },
        ],
    });
    apps.push(app);
    const w = app.world;
    const camera = w.create();
    w.add(camera, Transform, { translation: [0, 1.4, -1.8] });
    w.add(camera, InteractionInput);
    const target = box(w, [0, 1.4, -3.8]);
    const light = target;
    w.add(target, PointLight, { intensity: 0 });
    w.add(target, Usable, { action });
    w.resource(Content);
    w.tick();
    const step = (n = 1) => {
        for (let i = 0; i < n; i++) w.step(1 / 60);
    };
    step();
    return { w, camera, target, light, step };
}
function box(w: World, translation: readonly [number, number, number]) {
    const eid = w.create();
    w.add(eid, Transform, { translation });
    w.add(eid, Body, { type: BodyType.Static });
    w.add(eid, Shape);
    return eid;
}

test("in reach and in view focuses, outlines and shows the prompt", async () => {
    const { w, camera, target } = await scene();
    expect(w.storage(InteractionInput).target.get(camera)).toBe(target);
    expect(w.has(target, Outline)).toBe(true);
    expect(w.resource(Hint).target).toBe(target);
});

test("out of reach or behind a wall neither focuses nor outlines nor shows the prompt", async () => {
    const { w, camera, target, step } = await scene();
    w.storage(Transform).translation.z.set(camera, 2);
    step();
    expect(w.storage(InteractionInput).target.get(camera)).toBe(0);
    expect(w.has(target, Outline)).toBe(false);
    expect(w.resource(Hint).target).toBe(0);
    w.storage(Transform).translation.z.set(camera, -1.8);
    w.storage(Transform).rotation.set(camera, 0, 1, 0, 0);
    step();
    expect(w.storage(InteractionInput).target.get(camera)).toBe(0);
    expect(w.has(target, Outline)).toBe(false);
    expect(w.resource(Hint).target).toBe(0);
    w.storage(Transform).rotation.set(camera, 0, 0, 0, 1);
    box(w, [0, 1.4, -2.7]);
    w.tick();
    step();
    expect(w.storage(InteractionInput).target.get(camera)).toBe(0);
    expect(w.has(target, Outline)).toBe(false);
    expect(w.resource(Hint).target).toBe(0);
});

test("one press stays latched until a fixed tick and fires once", async () => {
    const { w, target, step } = await scene();
    pressKey(w, "KeyE");
    w.step(0);
    expect(w.storage(Usable).active.get(target)).toBe(0);
    for (let tick = 0; tick < 4; tick++) {
        step();
        expect(w.storage(Usable).active.get(target)).toBe(1);
    }
});

test("a hold fires on its completing tick, not before, and not again while held", async () => {
    const { w, target, step } = await scene(Action.Hold);
    pressKey(w, "KeyE");
    for (let tick = 0; tick < 59; tick++) {
        step();
        expect(w.storage(Usable).active.get(target)).toBe(0);
    }
    step();
    expect(w.storage(Usable).active.get(target)).toBe(1);
    for (let tick = 0; tick < 65; tick++) {
        step();
        expect(w.storage(Usable).active.get(target)).toBe(1);
    }
});

test("a hold resets on release or lost focus and requires a fresh press", async () => {
    const { w, target, camera, step } = await scene(Action.Hold);
    pressKey(w, "KeyE");
    step(30);
    releaseKey(w, "KeyE");
    step();
    expect(w.storage(InteractionInput).ticks.get(camera)).toBe(0);
    pressKey(w, "KeyE");
    step(30);
    w.storage(Transform).translation.x.set(camera, 5);
    step();
    expect(w.storage(InteractionInput).ticks.get(camera)).toBe(0);
    w.storage(Transform).translation.x.set(camera, 0);
    step(65);
    expect(w.storage(Usable).active.get(target)).toBe(0);
    releaseKey(w, "KeyE");
    step();
    pressKey(w, "KeyE");
    step(60);
    expect(w.storage(Usable).active.get(target)).toBe(1);
});

import {
    Camera,
    component,
    DirectionalLight,
    GlobalAmbientLight,
    lookAtRotation,
    Materials,
