import type { MaterialHandle } from "@dylanebert/shallot/standard/rendering";

export const WHITE: [number, number, number, number] = [1, 1, 1, 1];
export const GREEN: [number, number, number, number] = [0.03, 0.6, 0.08, 1];

/** The cube's material and whether space has turned it green. */
export const Cube: Resource<{ handle?: MaterialHandle; green: boolean }> = {
    create: () => ({ green: false }),
};

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xffffff;
    ambient.brightness = 500;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, -1, -2, -1.5) });
    world.add(sun, DirectionalLight, { color: 0xffffff, illuminance: 6000 });

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Transform, {
        translation: [3, 2.4, 4],
        rotation: lookAtRotation(3, 2.4, 4, 0, 0, 0),
    });

    const handle = world
        .resource(Materials)
        .add(StandardMaterial({ baseColor: WHITE, perceptualRoughness: 0.5 }));
    world.resource(Cube).handle = handle;
    const cube = world.create();
    world.add(cube, MeshInstance);
    world.add(cube, MeshMaterial, handle);
    world.add(cube, Transform);
}

/** Turns the cube green on the frame space is pressed; it stays green. */
const TurnGreenOnSpace: System = {
    name: "Cube/TurnGreenOnSpace",
    group: "setup",
    update(world) {
        const cube = world.resource(Cube);
        if (cube.green || !cube.handle) return;
        const devices = world.resource(Devices);
        if (!devices.enabled || !devices.keys.pressed.has("Space")) return;
        world.resource(Materials).update(cube.handle, { baseColor: GREEN });
        cube.green = true;
    },
};

export const CubePlugin: Plugin = {
    name: "Cube",
    dependencies: [InputPlugin],
    initialize: makeScene,
    systems: [TurnGreenOnSpace],
};

