import { pipelineWarnings, TIMEOUT } from "@dylanebert/shallot/testing";
import { expect, type Page, test } from "playwright/test";

test.use(pipelineWarnings);

async function centerColor(page: Page): Promise<[number, number, number]> {
    const screenshot = await page.locator("#canvas").screenshot();
    return page.evaluate(async (base64) => {
        const image = await createImageBitmap(
            new Blob([Uint8Array.from(atob(base64), (value) => value.charCodeAt(0))]),
        );
        const canvas = document.createElement("canvas");
        canvas.width = image.width;
        canvas.height = image.height;
        const context = canvas.getContext("2d")!;
        context.drawImage(image, 0, 0);
        const x = Math.floor(image.width / 2);
        const y = Math.floor(image.height / 2);
        const [r, g, b] = context.getImageData(x, y, 1, 1).data;
        image.close();
        return [r!, g!, b!] as [number, number, number];
    }, screenshot.toString("base64"));
}

const isWhite = ([r, g, b]: number[]) =>
    r! > 150 && Math.abs(r! - g!) < 25 && Math.abs(g! - b!) < 25;
const isGreen = ([r, g, b]: number[]) => g! > 80 && g! > r! * 2 && g! > b! * 2;

test("the cube is white until space, then green and stays green", async ({ page }) => {
    await page.goto("/");
    await expect(page.locator("body > [data-shallot-loading]")).toHaveCount(0, {
        timeout: TIMEOUT.browser,
    });
    await expect.poll(() => centerColor(page), { timeout: TIMEOUT.browser }).toSatisfy(isWhite);
    await page.waitForTimeout(300);
    expect(isWhite(await centerColor(page))).toBe(true);

    await page.keyboard.press("Space");
    await expect.poll(() => centerColor(page), { timeout: 2000 }).toSatisfy(isGreen);
    await page.waitForTimeout(300);
    expect(isGreen(await centerColor(page))).toBe(true);
    if (process.env.SHALLOT_CAPTURE_DIR)
        await page.screenshot({ path: `${process.env.SHALLOT_CAPTURE_DIR}/green.png` });
});
